from collections import Counter
from itertools import combinations, product
import heapq


def _build_interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best = None
        best_ids = None
        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory <= ids or blocked & ids:
                continue
            counts = Counter(job["group"] for job in subset)
            if any(not low <= counts[group] <= high
                   for group, (low, high) in quotas.items()):
                continue
            active = []
            valid = True
            for job in sorted(subset, key=lambda j: (j["start"], j["end"], j["id"])):
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in subset)
            selected = sorted(ids)
            if (best is None or value > best or
                    (value == best and (selected < best_ids if tie == "smallest"
                                        else selected > best_ids))):
                best, best_ids = value, selected
        if best is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best}
    return solve


def _build_component_06():
    def rounded(n, mode):
        return (n + 5000) // 10000 if mode == "half_up" else n // 10000

    def solve(data):
        winners = {}
        cutoff = data.get("cutoff", 10**9)
        for pos, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (event.get("revision", 0), pos)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)
        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        domains = []
        for name in names:
            versions = sorted({row["version"] for row in packages[name]})
            domains.append([-1] + versions)

        def valid(vector):
            chosen = {name: version for name, version in zip(names, vector)
                      if version != -1}
            for name, bounds in roots.items():
                version = chosen.get(name)
                if version is None or not bounds[0] <= version <= bounds[1]:
                    return False
            for name, version in chosen.items():
                if version in blocked.get(name, []):
                    return False
                if name in pins and pins[name] != version:
                    return False
            rows = {name: next((r for r in packages[name]
                                if r["version"] == version), None)
                    for name, version in chosen.items()}
            edges = {name: [] for name in chosen}
            for name, row in rows.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    version = chosen.get(target)
                    if version is None or not dep["min"] <= version <= dep["max"]:
                        return False
                    edges[name].append(target)
            # Installed packages must be precisely the closure reachable from roots.
            reached, todo = set(), list(roots)
            while todo:
                name = todo.pop()
                if name in reached:
                    continue
                reached.add(name)
                if name not in rows:
                    return False
                todo.extend(edges[name])
            if reached != set(chosen):
                return False
            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            return all(visit(name) for name in edges)

        for vector in product(*domains):
            if valid(vector):
                return {"versions": {name: version for name, version in zip(names, vector)
                                     if version != -1}}
        return {"error": "unsatisfiable"}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bits = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source = data["source"]
        initial_mask = bits.get(source, 0)
        start_state = (source, initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]
        while queue:
            time, node, mask, coupons = heapq.heappop(queue)
            state = (node, mask, coupons)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], coupons)]
                if coupons:
                    options.append((max(2, edge["duration"] - edge.get("discount", 0)), coupons - 1))
                for duration, left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    dest = edge["v"]
                    next_mask = mask | bits.get(dest, 0)
                    next_state = (dest, next_mask, left)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, dest, next_mask, left))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_interval_solver(1, "smallest"),
    "component_02": _build_interval_solver(2, "smallest"),
    "component_03": _build_interval_solver(1, "largest"),
    "component_04": _build_interval_solver(2, "largest"),
    "component_05": _build_interval_solver(1, "smallest"),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
